// Задание 8: Реле вибрации
const int sensorPin = 6;
const int relayPin = 11;
const int threshold = 100; // Порог срабатывания вибрации (настраивается)

void setup() {
  Serial.begin(9600);
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  int vibration = analogRead(sensorPin);
  Serial.print("Уровень вибрации: ");
  Serial.println(vibration);

  if (vibration > threshold) {
    digitalWrite(relayPin, HIGH);
    Serial.println("Обнаружена вибрация!");
  } else {
    digitalWrite(relayPin, LOW);
  }
  delay(200); // Малая задержка для быстрой реакции
}
